export const Dashboard: React.FC<DashboardProps> = ({ user, onLogout }) => {
  const [activeView, setActiveView] = useState<View>('overview');
  const [sidebarMode, setSidebarMode] = useState<'agents' | 'dashboard'>('dashboard');
  const [activeAgent, setActiveAgent] = useState<AgentType | null>(null);
  const [currentLanguage, setCurrentLanguage] = useState(user.language);
  const [selectedWorkflow, setSelectedWorkflow] = useState<any>(null);

  // Chat State
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [showAppsLibrary, setShowAppsLibrary] = useState(false);
  const [showTemplatesLibrary, setShowTemplatesLibrary] = useState(false);
  const [showEditWorkflow, setShowEditWorkflow] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const [langNotification, setLangNotification] = useState('');

  // Initial State Setup
  useEffect(() => {
    // Default to Dashboard Overview on load
    setSidebarMode('dashboard');
    setActiveView('overview');
  }, []);

  const changeLanguage = (lang: string) => {
      setCurrentLanguage(lang);
      setLangNotification(`Language changed successfully to ${lang}. The UI will now update.`);
      setTimeout(() => setLangNotification(''), 3000);
  };

  const handleAgentSelect = (agent: AgentType) => {
    setActiveAgent(agent);
    setActiveView('chat');
    // Agent Switching Logic: Clear Content & Show Welcome
    setMessages([{
        role: 'model',
        text: `Hello! I am your **${agent} Agent**. \n\nI can help you with specific tasks related to ${agent}. Check out the Quick Run templates below.`,
        timestamp: Date.now()
    }]);
  };

  const switchToDashboard = () => {
      setSidebarMode('dashboard');
      setActiveView('overview');
      setActiveAgent(null);
  };

  const switchToChat = () => {
      setSidebarMode('agents');
      // If no agent selected, select Sales by default
      if (!activeAgent) handleAgentSelect('Sales');
      else setActiveView('chat');
  };

  const openWorkflowDetail = (workflow: any) => {
      setSelectedWorkflow(workflow);
      setActiveView('workflow_detail');
  };

  const handleSendMessage = async (textOverride?: string) => {
    const textToSend = textOverride || input;
    if (!textToSend.trim() || isLoading) return;

    const userMsg: ChatMessage = { role: 'user', text: textToSend, timestamp: Date.now() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    try {
        // Construct history, removing the synthetic welcome message (index 0 if model)
        // to prevent API errors about invalid history structure.
        const historyForModel = messages
            .filter((msg, index) => !(index === 0 && msg.role === 'model'))
            .map(m => ({
                role: m.role,
                parts: [{ text: m.text }]
            }));

        const responseText = await chatWithBot(
            historyForModel, 
            textToSend, 
            'gemini-3-pro-preview', 
            currentLanguage,
            FINAL_CONSTITUTION_PROMPT
        );

        setMessages(prev => [...prev, {
            role: 'model',
            text: responseText,
            timestamp: Date.now()
        }]);
    } catch (error) {
        setMessages(prev => [...prev, {
            role: 'model',
            text: "I encountered a connection error. Please check your network and try again.",
            timestamp: Date.now()
        }]);
    } finally {
        setIsLoading(false);
    }
  };

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  return (
    <div className="flex h-screen bg-slate-50 dark:bg-[#020617] text-slate-900 dark:text-slate-200 overflow-hidden font-sans">

