                    {[
                        { type: 'Sales', icon: TrendingUp, color: 'text-green-500' },
                        { type: 'Support', icon: Headphones, color: 'text-blue-500' },
                        { type: 'HR Recruiter', icon: Users, color: 'text-purple-500' },
                        { type: 'Operations', icon: Briefcase, color: 'text-orange-500' },
                        { type: 'Tax/GST', icon: DollarSign, color: 'text-yellow-500' },
                        { type: 'Data Analyst', icon: BarChart2, color: 'text-teal-500' },
                        { type: 'Meeting Scheduled', icon: Clock, color: 'text-pink-500' },
                        { type: 'Marketing', icon: Video, color: 'text-rose-500' },
                        { type: 'Help', icon: Bot, color: 'text-slate-400' },
